//! INDEPENDENT differential suite for balanced38.
//!
//! The corpus (`oracle_corpus.txt`) is generated by the **Python oracle**
//! (`scripts/emit_balanced38_corpus.py`, which reuses
//! `scripts/base38_oracle.py`) — a from-spec, arbitrary-precision Python
//! engine using the dense integer alphabet `0-9 A-Z a b`. No Rust lane
//! participated in its construction, so the two engines can never share
//! a bug silently: a genuinely independent cross-check, value-level.
//!
//! balanced38 is an i128-shore lane, so the corpus only emits values
//! 0 <= n <= i128::MAX. 52 of the 3,145 lines exceed 38^24 - 1 (up to
//! i128::MAX) but stay inside the i128 shore. Values the lane refuses
//! by contract, and the negative half, are covered by the unit suite
//! and the negative cases below.
//!
//! Regenerate the corpus with:
//!     python3 scripts/emit_balanced38_corpus.py \
//!         > crates/balanced38/tests/oracle_corpus.txt

use balanced38::Balanced38;

/// The oracle's dense alphabet (identical contract to base38_oracle.py:
/// 0-9 A-Z a b). Independent re-derivation in Rust — alphabet only.
const DENSE: &[u8; 38] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZab";

fn dense_value(ch: u8) -> Option<u128> {
    match ch {
        b'0'..=b'9' => Some(u128::from(ch - b'0')),
        b'A'..=b'Z' => Some(u128::from(ch - b'A') + 10),
        b'a' => Some(36),
        b'b' => Some(37),
        _ => None,
    }
}

/// Decode a dense base-38 string (LSB→MSB Horner) in u128, exactly as
/// the oracle's `decode` does. Independent of the balanced lane.
fn decode_dense(s: &str) -> Option<u128> {
    let mut acc: u128 = 0u128;
    for &ch in s.as_bytes() {
        acc = acc.checked_mul(38)?.checked_add(dense_value(ch)?)?;
    }
    Some(acc)
}

fn corpus_lines() -> impl Iterator<Item = (u128, &'static str)> {
    include_str!("oracle_corpus.txt").lines().map(|line| {
        let (n, s) = line.split_once(' ').expect("oracle emits 'n encoded'");
        (n.parse().expect("oracle emits u128-comparable n"), s)
    })
}

/// THE ALPHABET MIRROR: every dense digit maps to its index, both ways —
/// the decoder's contract with the oracle, locked.
#[test]
fn the_dense_alphabet_mirror() {
    for (i, &ch) in DENSE.iter().enumerate() {
        assert_eq!(
            dense_value(ch),
            Some(i as u128),
            "mirror broke at index {i}"
        );
    }
    for &bad in b"!@#z~_ \t".iter() {
        assert_eq!(dense_value(bad), None, "{bad:?} is not a dense digit");
    }
}

/// THE VALUE LAW: the oracle's encoding, decoded independently in Rust,
/// reads back exactly — and the balanced lane (the residue walk) folds
/// the same value back to itself.
#[test]
fn the_oracle_decodes_and_the_lane_folds_back() {
    let mut n = 0u64;
    for (v, encoded) in corpus_lines() {
        n += 1;
        assert_eq!(decode_dense(encoded), Some(v), "decode broke for {encoded}");
        // in-shore by construction; the residue walk must round-trip
        let bal = Balanced38::from_i128(v as i128);
        assert_eq!(bal.to_i128(), v as i128, "fold-back broke at {v}");
    }
    assert_eq!(n, 3145, "the corpus must stay the shipped receipt");
}

/// THE CANONICAL SHAPE: a value the oracle wrote never folds to a
/// trailing gap (except the Void itself) — the residue walk's contract.
#[test]
fn the_walk_never_ends_on_a_gap() {
    for (v, encoded) in corpus_lines() {
        let bal = Balanced38::from_i128(v as i128);
        if v == 0 {
            assert!(bal.is_zero(), "the Void is the empty string");
        } else {
            assert_ne!(
                bal.as_digits().last(),
                Some(&0),
                "trailing gap at {v} ({encoded})"
            );
        }
    }
}

/// THE DIFFERENTIAL ADD LAW: consecutive corpus values a, b — the lane's
/// own add must deliver the exact in-shore sum the oracle already carries.
/// Pairs whose sum crosses the i128 shore are outside the lane's contract
/// and skipped — the shore is tested by the unit suite.
#[test]
fn the_differential_add_law() {
    let vals: Vec<u128> = corpus_lines().map(|(v, _)| v).collect();
    let mut checked = 0u64;
    for w in vals.windows(2) {
        let (a, b) = (w[0] as i128, w[1] as i128);
        let Some(sum) = a.checked_add(b) else {
            continue; // beyond the lane's shore — not its contract
        };
        checked += 1;
        assert_eq!(
            Balanced38::from_i128(a)
                .checked_add(&Balanced38::from_i128(b))
                .to_i128(),
            sum,
            "differential add broke at {a}+{b}"
        );
    }
    assert!(checked > 2000, "the add law actually ran");
}

/// THE NEGATIVE LANE: the corpus is nonnegative, so the signed half is
/// checked here against exact i128 cases, including MIN and the shore
/// edges. `wrapping_neg` is the i128-edge mirror for MIN.
#[test]
fn the_negative_lane_round_trips() {
    let cases = [
        i128::MIN,
        i128::MIN + 1,
        -1,
        -19,
        -20,
        -38,
        -39,
        -(1i128 << 64),
        -i128::MAX,
    ];
    for &v in &cases {
        let b = Balanced38::from_i128(v);
        assert_eq!(b.checked_to_i128(), Some(v), "checked fold at {v}");
        assert_eq!(b.to_i128(), v, "fast fold at {v}");
        assert_eq!(b.negate().to_i128(), v.wrapping_neg(), "mirror at {v}");
    }
}
